// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _run(string memory description) internal {
        vm.assume(c.jojoTeam() != address(this));
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.jojoTeam() != address(this));
    }

    function testFuzz_run(string memory description) public {
        _run(description);
    }

    receive() external payable {}
}
